import json

descriptions = {
    "louis-xiv": "Louis XIV ruled France for 72 years, longer than any other major European monarch, and built the Palace of Versailles to display his absolute power. He moved the French government to Versailles and required thousands of nobles to live there so he could watch over them.",
    "marie-antoinette": "Marie Antoinette was the Austrian princess who became Queen of France at age 18 and became a symbol of royal excess during a time of poverty and revolution. She was executed by guillotine in 1793 during the French Revolution, just months after her husband King Louis XVI.",
    "andre-le-notre": "André Le Nôtre designed the grand gardens of Versailles, inventing the French formal garden style with its precise geometry, fountains, and mile-long perspectives. His work transformed landscape design across Europe and his plans for Versailles required moving over six million cubic meters of earth.",
    "emperor-vespasian": "Emperor Vespasian ordered the construction of the Colosseum in 72 AD, funding it with treasures looted from the Temple of Jerusalem. He came from a humble background and was known for his practical, no-nonsense style of rule compared to the extravagance of earlier emperors.",
    "gladiator-spartacus": "Spartacus was a Thracian slave who escaped a gladiatorial training school in 73 BC and led an army of up to 120,000 escaped slaves across Italy in a rebellion that terrified Rome. He was killed in battle in 71 BC, and 6,000 of his followers were crucified along the Appian Way as a warning.",
    "livia-drusilla": "Livia Drusilla was the wife of Rome's first emperor Augustus and one of the most powerful women in Roman history, widely believed to have influenced key political decisions from behind the scenes. She outlived Augustus by 15 years and was eventually declared a goddess by the Emperor Claudius.",
    "pericles": "Pericles was the democratic statesman who led Athens during its golden age in the 5th century BC, commissioning the Parthenon and other monuments that still define the Acropolis today. He opened political participation to more citizens and made Athens the cultural and intellectual center of the ancient world.",
    "socrates": "Socrates was an Athenian philosopher who developed a method of questioning — the Socratic method — that is still used in law schools and universities today. He was put on trial for 'corrupting the youth' and 'impiety,' found guilty, and chose to drink hemlock rather than flee Athens.",
    "aspasia": "Aspasia was an immigrant woman from Miletus who became one of the most educated and influential people in Athens, serving as the companion and intellectual partner of Pericles. Ancient writers credited her with writing some of Pericles' greatest speeches, though as a foreign woman she could not be a citizen.",
    "stone-builder": "The builders of Stonehenge transported massive sarsen stones weighing up to 25 tons from quarries 25 miles away, using only human strength, wooden sledges, and ropes. Construction of Stonehenge took place over roughly 1,500 years, from about 3000 to 1500 BC, involving generations of communities.",
    "stone-astronomer": "Stonehenge is precisely aligned with the sunrise on the summer solstice and the sunset on the winter solstice, suggesting it served as an astronomical calendar for its builders. The people who built it left no written records, so much of their knowledge and purpose must be pieced together from the stones themselves.",
    "boudica": "Boudica was queen of the Iceni tribe in Britain who led a massive uprising against the Roman occupiers around 60 AD, burning the Roman cities of Camulodunum, Londinium, and Verulamium to the ground. Her rebellion was eventually crushed by the Roman governor Paulinus, and she is believed to have taken poison to avoid capture.",
    "william-the-conqueror": "William the Conqueror was the Duke of Normandy who invaded England in 1066, defeated King Harold at the Battle of Hastings, and transformed English language, law, and culture with French and Latin influences. He commissioned the Domesday Book, a detailed survey of all land and property in England that remains a vital historical record.",
    "anne-boleyn": "Anne Boleyn was the second wife of King Henry VIII, and her failure to produce a male heir led Henry to have her arrested on charges of treason and adultery, which most historians believe were fabricated. Her execution in 1536 shocked European courts, and her daughter went on to become Queen Elizabeth I, one of England's greatest monarchs.",
    "guy-fawkes": "Guy Fawkes was a Catholic conspirator who planned to blow up the Houses of Parliament on November 5, 1605 by placing 36 barrels of gunpowder beneath the building — a plot known as the Gunpowder Plot. He was caught, tortured, and executed, but his effigy is burned every year in Britain on Bonfire Night to commemorate the plot's failure.",
    "muhammad-v": "Muhammad V was the Sultan of Granada who presided over a golden age of Nasrid culture, commissioning the exquisite Comares Tower and Court of the Lions within the Alhambra palace complex. Despite being deposed twice and spending years in exile in Morocco, he ultimately regained his throne and ruled until 1391.",
    "fatima-al-fihri": "Fatima al-Fihri founded the University of al-Qarawiyyin in Fez, Morocco in 859 AD, which is recognized by UNESCO as the world's oldest continuously operating university. She used her entire inheritance to build the mosque and school, and oversaw its construction herself, fasting until the project was complete.",
    "washington-irving": "Washington Irving was an American author best known for 'Rip Van Winkle' and 'The Legend of Sleepy Hollow,' but he also lived in the Alhambra palace for several months in 1829 and wrote 'Tales of the Alhambra,' which brought the palace's legends to worldwide audiences. His vivid descriptions inspired a surge of European and American interest in Spanish Moorish architecture.",
    "pliny-the-elder": "Pliny the Elder was a Roman admiral and natural philosopher who wrote a 37-volume encyclopedia called 'Natural History' attempting to describe all ancient knowledge about the world. He died during the eruption of Mount Vesuvius in 79 AD while trying to rescue survivors by ship, making him one of history's most famous scientific martyrs.",
    "eumachia": "Eumachia was one of the most powerful and wealthy women in Pompeii, who used her fortune to construct the largest building in the Forum, dedicated to Concordia Augusta and the patron goddess of the cloth trade. Her prominence in public life challenged the common assumption that Roman women had no role outside the home.",
    "pompeii-baker": "Terentius Neo was a baker in Pompeii whose portrait, along with his wife's, was preserved on a fresco that survived the eruption of Mount Vesuvius in 79 AD — he holds a scroll, suggesting he was literate and proud of it. His bakery, complete with stone mills and an oven, was excavated and can still be visited today.",
    "justinian-i": "Emperor Justinian I ruled the Byzantine Empire from 527 to 565 AD and oversaw the compilation of Roman law into the Corpus Juris Civilis, which became the foundation of legal systems across Europe. He also ordered the complete rebuilding of the Hagia Sophia after the original church was destroyed in a riot, creating one of the world's greatest architectural achievements.",
    "theodora": "Theodora was a former actress who rose to become Empress of Byzantium and arguably the most powerful woman in the ancient world, co-ruling alongside her husband Justinian I. When a riot in Constantinople threatened to overthrow the government in 532 AD, it was Theodora who convinced Justinian to stay and fight rather than flee, saving the empire.",
    "isidore-of-miletus": "Isidore of Miletus was one of the two chief architects commissioned by Emperor Justinian to design the Hagia Sophia, which was completed in just five years between 532 and 537 AD. He pioneered the use of pendentives — curved triangular sections — to support the massive dome over a square base, solving an engineering problem that had never been attempted at that scale.",
    "ivan-the-great": "Ivan III, known as Ivan the Great, was the Grand Prince of Moscow who tripled the size of Russian territory, ended Mongol dominance over Russia, and established Moscow as the 'Third Rome' after the fall of Constantinople. He hired Italian architects to rebuild and expand the Kremlin, giving it the recognizable red-brick walls and towers that still stand today.",
    "catherine-the-great": "Catherine the Great was a German princess who married into the Russian royal family and eventually seized power from her own husband in a coup, ruling Russia for 34 years as one of its most effective leaders. She expanded the Russian Empire significantly, modernized the country's laws and education, and was a major patron of the arts who founded the Hermitage Museum.",
    "andrei-rublev": "Andrei Rublev was a Russian Orthodox monk and icon painter of the early 15th century, widely considered the greatest Russian painter of medieval times, whose works were so revered that the church later made him a saint. His most famous work, 'Trinity,' depicted the three angels who visited Abraham and became the defining image of Russian Orthodox Christian art.",
    "mary-queen-of-scots": "Mary, Queen of Scots became queen of Scotland when she was just six days old, and her life was marked by political turbulence, three marriages, and her claim to the English throne as a great-great-granddaughter of Henry VII. After being forced to abdicate, she fled to England and was imprisoned by her cousin Queen Elizabeth I for 19 years before being executed for alleged treason.",
    "robert-the-bruce": "Robert the Bruce was the Scottish king who led the Wars of Scottish Independence against England, most famously defeating a much larger English army at the Battle of Bannockburn in 1314. He secured Scottish independence with the Declaration of Arbroath in 1320 and is remembered as one of Scotland's greatest national heroes.",
    "greyfriars-bobby-owner": "John Gray was an Edinburgh night watchman in the 1850s who owned a Skye terrier named Bobby that became famous for guarding his master's grave in Greyfriars Kirkyard for 14 years after Gray's death in 1858. Bobby's loyalty became so well-known that a small statue was erected in his honor near the cemetery and still stands today.",
    "pharaoh-khufu": "Pharaoh Khufu commissioned the Great Pyramid of Giza around 2560 BC — a structure of 2.3 million stone blocks that remained the tallest man-made structure in the world for nearly 4,000 years. Despite his monumental achievement, almost nothing else is known about his personality or reign, and the only confirmed portrait of him is a tiny 3-inch ivory figurine.",
    "cleopatra": "Cleopatra VII was the last active ruler of the Ptolemaic Kingdom of Egypt, and she was the first member of her dynasty to actually learn to speak Egyptian — her family had ruled for 275 years speaking only Greek. She formed powerful alliances with Julius Caesar and Mark Antony, and her death in 30 BC ended 3,000 years of Egyptian pharaonic rule.",
    "hemiunu": "Hemiunu was the royal vizier and chief architect who oversaw the construction of the Great Pyramid of Giza for Pharaoh Khufu, managing a workforce estimated at 20,000–30,000 workers. His own large mastaba tomb was built near the pyramid he designed, and a striking painted limestone statue of him was discovered inside it in the early 20th century.",
    "tutankhamun": "Tutankhamun became Pharaoh of Egypt at approximately age 9 and died at around 18 or 19, but he is one of the most famous pharaohs in history because his tomb was discovered nearly intact in 1922 with over 5,000 artifacts inside. DNA testing and CT scans of his mummy have revealed he suffered from multiple diseases and a broken leg that may have contributed to his early death.",
    "hatshepsut": "Hatshepsut was one of ancient Egypt's most successful pharaohs, ruling for around 20 years as a female king — she even wore a false beard in official portraits to conform to the visual tradition of male kingship. After her death, her successor Thutmose III systematically destroyed or defaced her images and monuments, and her identity was not rediscovered by modern scholars until the 20th century.",
    "howard-carter": "Howard Carter was a British archaeologist who spent years searching the Valley of the Kings before discovering Tutankhamun's nearly intact tomb on November 4, 1922 — the most spectacular archaeological find of the 20th century. The discovery took ten years to fully document and clear, and Carter spent the rest of his life overseeing the meticulous recording and preservation of its contents.",
    "mutota": "Nyatsimba Mutota was the founder of the Mutapa Empire in the 15th century, expanding from Great Zimbabwe northward into present-day Zimbabwe and Mozambique to control the gold and ivory trade routes to the Swahili coast. His empire, known as Mwene Mutapa, became one of the wealthiest and most powerful states in southern Africa.",
    "zimbabwe-trader": "Great Zimbabwe was a major hub in the Indian Ocean trade network, and Swahili merchants from the East African coast traveled inland to exchange porcelain, glass beads, and cloth for gold, ivory, and iron produced in the interior. Archaeological evidence of Chinese porcelain and Persian pottery found at Great Zimbabwe shows how globally connected this civilization was.",
    "zimbabwe-builder": "The stone walls of Great Zimbabwe were constructed without mortar using a dry-stone technique, and the builders achieved remarkable precision by selecting and shaping granite blocks to fit tightly together. The Great Enclosure's outer wall is 250 meters long and up to 11 meters tall, representing one of the most impressive pre-colonial architectural achievements in sub-Saharan Africa.",
    "mansa-musa": "Mansa Musa was the Emperor of the Mali Empire and is often cited as the wealthiest person in all of human history, with a fortune derived from Mali's vast reserves of gold and salt. His famous pilgrimage to Mecca in 1324 — during which he reportedly gave away so much gold that he caused inflation across North Africa and the Middle East — put Mali on European maps for the first time.",
    "timbuktu-scholar": "Ahmed Baba al-Massufi was Timbuktu's greatest scholar, authoring over 40 books on Islamic law, theology, and history, and amassing a personal library of over 1,600 manuscripts. When the Moroccan army conquered Timbuktu in 1591, he was arrested and exiled to Marrakech, where he continued to teach and write until he was allowed to return home 12 years later.",
    "timbuktu-salt-trader": "Timbuktu sat at the crossroads of two of West Africa's most vital trade routes — the trans-Saharan caravan route from the north bringing salt and horses, and the Niger River route from the south bringing gold and kola nuts. Salt was so valuable in the Sahel region, where it was essential for preserving food and human health, that it was sometimes traded pound-for-pound with gold.",
    "king-lalibela": "King Lalibela ruled the Zagwe dynasty of Ethiopia in the early 13th century and commissioned eleven extraordinary churches carved entirely out of solid rock, creating an underground sacred city that pilgrims still visit today. Legend says he traveled to Jerusalem and wanted to create a 'New Jerusalem' in Ethiopia so his people could make pilgrimage without the dangerous journey to the Holy Land.",
    "lalibela-carver": "The rock-hewn churches of Lalibela are among the most remarkable feats of engineering in the medieval world — craftsmen carved downward through solid volcanic basalt, creating entire church buildings, complete with windows, doors, and interior columns, entirely below ground level. The largest, Bete Medhane Alem, stands 12 meters tall and is believed to be the largest rock-hewn church in the world.",
    "queen-of-sheba": "The Queen of Sheba, known in Ethiopia as Makeda, is a legendary figure who according to the Bible and Quran visited King Solomon in Jerusalem, and in Ethiopian tradition she became the ancestor of the Ethiopian royal line. Ethiopian emperors, including Haile Selassie in the 20th century, traced their lineage back to the son born of her union with Solomon.",
    "hannibal-barca": "Hannibal Barca was the Carthaginian general who launched one of the most daring military campaigns in history, leading an army of 50,000 soldiers and war elephants across the Alps into Italy in 218 BC. He won several crushing victories against Roman armies but was ultimately unable to take Rome itself, and Carthage was defeated and destroyed by Rome in 146 BC.",
    "dido": "Queen Dido, also known as Elissa, was the legendary Phoenician princess who escaped her murderous brother, sailed to North Africa, and cleverly acquired land for a new city by asking for only as much land as could be covered by an ox hide — then cutting the hide into thin strips to encircle a whole hilltop. Carthage grew from that settlement to become one of the most powerful cities in the ancient Mediterranean world.",
    "carthage-sailor": "Hanno the Navigator was a Carthaginian explorer who led an expedition of 60 ships and 30,000 colonists along the coast of West Africa around 500 BC, establishing settlements and sailing farther down the African coast than any known explorer before him. His account, inscribed on a bronze tablet in Carthage, describes encountering gorillas — the first recorded description of great apes by a western explorer.",
    "nelson-mandela": "Nelson Mandela was a South African anti-apartheid activist who was imprisoned for 27 years on Robben Island for his resistance to the white-minority apartheid government, and upon his release in 1990 he led peaceful negotiations that ended apartheid and resulted in South Africa's first democratic elections. He became South Africa's first Black president in 1994 and is celebrated worldwide as a symbol of reconciliation, forgiveness, and the long struggle for human dignity.",
    "walter-sisulu": "Walter Sisulu was one of the most important leaders of the African National Congress and a close mentor of Nelson Mandela, who introduced Mandela to the ANC and supported him throughout the anti-apartheid struggle. He was sentenced to life imprisonment alongside Mandela at the Rivonia Trial in 1964 and spent 26 years on Robben Island before being released in 1989.",
    "ahmed-kathrada": "Ahmed Kathrada was a South African anti-apartheid activist of Indian descent who was sentenced to life imprisonment at the Rivonia Trial in 1964 and spent 26 years in Robben Island prison, sharing a cell block with Nelson Mandela. After his release, he became a member of parliament, served as a political advisor to Mandela's government, and spent his later years preserving the history of the anti-apartheid struggle.",
    "elmina-guide": "Elmina Castle on the coast of Ghana was built by the Portuguese in 1482, making it the oldest European building in sub-Saharan Africa, and later became the largest slave-trading post on the West African coast during the transatlantic slave trade. Millions of enslaved Africans passed through its dungeons before being shipped across the Atlantic, and the castle today serves as a memorial and UNESCO World Heritage Site.",
    "yaa-asantewaa": "Yaa Asantewaa was the Queen Mother of Ejisu in the Ashanti Empire who led the War of the Golden Stool in 1900 — the last major Ashanti resistance against British colonialism — when the male chiefs hesitated to fight. She was captured and exiled to the Seychelles, where she died in 1921, and is remembered today as one of Africa's greatest female military leaders.",
    "nana-esi": "Elmina has been a fishing community on Ghana's coast for centuries, and Fante women have long been central to the local economy, controlling the fish trade and negotiating between the European fort merchants and local traders. The relationship between the African fishing communities and the European traders at Elmina Castle was complex, involving both commerce and deep moral compromises as the slave trade developed.",
    "aretas-iv": "Aretas IV was the most powerful Nabataean king, ruling for nearly 50 years from around 9 BC to 40 AD, during which Petra reached its peak of prosperity as a center of the incense and spice trade between Arabia, India, and the Mediterranean. He was also the father-in-law of Herod Antipas, putting him in the middle of New Testament-era politics in the region.",
    "nabataean-water-engineer": "The Nabataeans were masters of water engineering in one of the most arid landscapes on earth, building an elaborate system of channels, cisterns, and dams that could capture and store every drop of flash-flood rainwater to sustain a city of 20,000 people in the desert. Archaeologists have found over 200 cisterns carved into the rocks around Petra, demonstrating a sophisticated understanding of hydrology.",
    "petra-trader": "Petra controlled a critical junction of ancient trade routes carrying frankincense, myrrh, and spices from Arabia and India to markets in Egypt, Syria, Greece, and Rome, allowing the Nabataeans to charge substantial tolls on every caravan that passed through. At its peak, Petra handled trade goods worth the equivalent of hundreds of millions of dollars annually in today's terms.",
    "king-solomon": "King Solomon ruled the Kingdom of Israel around 970–931 BC and built the First Temple in Jerusalem to house the Ark of the Covenant, making Jerusalem the religious center of the Jewish world. He is also credited with writing several books of the Bible, including Proverbs, Ecclesiastes, and the Song of Solomon, and is remembered in Jewish, Christian, and Islamic traditions as a figure of great wisdom.",
    "saladin": "Saladin was the Kurdish Muslim sultan who united Egypt and Syria, and in 1187 recaptured Jerusalem from the Crusaders who had held it for 88 years — yet was widely praised even by Christian chroniclers for his chivalry and mercy in victory. He spent most of his personal fortune on charitable works and died with almost nothing in his treasury despite having ruled vast territories.",
    "helena": "Saint Helena was the mother of the Emperor Constantine and traveled to the Holy Land around 326 AD on one of the first Christian pilgrimages, claiming to have discovered the True Cross and the sites of Jesus's birth, crucifixion, and resurrection. She commissioned the Church of the Holy Sepulchre and the Church of the Nativity, establishing the tradition of Christian pilgrimage to Jerusalem that continues to this day.",
    "cyrus-the-great": "Cyrus the Great founded the Achaemenid Persian Empire around 550 BC by conquering the Median, Lydian, and Babylonian empires in quick succession, creating the largest empire the world had yet seen. He was remarkable for his policy of tolerance — allowing conquered peoples to keep their religions and customs — and his Cyrus Cylinder is sometimes called the world's first declaration of human rights.",
    "darius-the-great": "Darius the Great expanded the Persian Empire to its greatest extent, ruling over an estimated 44% of the world's population at the time, and built Persepolis as a magnificent ceremonial capital to showcase Persian power and receive tribute from his 23 conquered nations. He also introduced standardized weights and measures, a postal system, and a network of roads that enabled trade and communication across his vast empire.",
    "artemisia-i": "Artemisia I was a Greek queen of Halicarnassus who voluntarily commanded her own fleet as an ally of the Persian king Xerxes in his invasion of Greece, becoming one of the very few female commanders in ancient naval history. Herodotus reported that Xerxes admired her counsel more than that of his other admirals, and she was the only commander to advise him against fighting the Greeks at the Battle of Salamis — advice he ignored to his great cost.",
    "shah-jahan": "Shah Jahan was the Mughal Emperor who commissioned the Taj Mahal as a mausoleum for his beloved wife Mumtaz Mahal, who died in 1631 during the birth of their 14th child. He was later overthrown and imprisoned by his own son Aurangzeb, and spent the last eight years of his life confined to a room in Agra Fort with a view of the Taj Mahal across the river.",
    "mumtaz-mahal": "Mumtaz Mahal was the favorite wife of Emperor Shah Jahan, accompanying him on military campaigns and serving as his close advisor, and her death in 1631 reportedly left the emperor grief-stricken and caused his hair to turn white overnight. The Taj Mahal, built over 22 years by 20,000 workers, is considered one of the greatest love monuments ever created.",
    "ustad-ahmad-lahori": "Ustad Ahmad Lahori is the architect most widely credited with designing the Taj Mahal, serving as the chief architect in the Mughal imperial court. He oversaw the construction of an extraordinary complex that required mathematicians, calligraphers, gem-setters, and masons from across the Mughal Empire and as far away as Persia, Turkey, and Europe.",
    "kashyapa-i": "King Kashyapa I of Sri Lanka built his legendary palace complex on top of the 200-meter-high Sigiriya rock fortress between 477 and 495 AD, after killing his father the king and needing an impregnable stronghold that only he could reach. He lined the approach path with dramatic paintings of heavenly maidens (the Sigiriya frescoes) and covered the rock's western face with a giant painting of a crouching lion whose paws still survive.",
    "sigiriya-painter": "The Sigiriya frescoes are paintings of elegant, jeweled female figures depicted on the sheer rock face at Sigiriya, and they are among the best-preserved examples of ancient South Asian painting, showing sophisticated use of color, shading, and perspective. Only about 21 of the original paintings survive today, but ancient graffiti inscribed on the mirror-polished plaster wall below suggests there were once hundreds.",
    "sigiriya-garden-designer": "The water gardens of Sigiriya are considered among the world's oldest surviving examples of landscape architecture, featuring a hydraulic system of cisterns, conduits, and fountains that operated entirely by water pressure without any mechanical pumps. The symmetrical gardens to the west of the rock were designed to be approached along a precise axis, creating theatrical vistas of the rock fortress as visitors moved through them.",
    "qin-shi-huang": "Qin Shi Huang unified China for the first time in 221 BC by conquering six rival kingdoms, standardized the writing system, currency, and weights and measures across his empire, and connected existing walls to create an early version of the Great Wall. He was so obsessed with immortality that he drank mercury-laced 'immortality potions' which probably contributed to his death at age 49.",
    "hua-mulan": "Hua Mulan is a legendary Chinese warrior who, according to a 6th-century poem called the Ballad of Mulan, disguised herself as a man to serve in the army in her elderly father's place. The story has been retold across 1,500 years of Chinese literature and has become one of the most beloved tales of loyalty and female courage in Chinese culture.",
    "wall-builder": "The Great Wall of China was not built all at once — it was constructed, extended, and rebuilt by multiple dynasties over more than 2,000 years, with the most famous sections built during the Ming Dynasty (1368–1644). It is estimated that hundreds of thousands, possibly millions, of laborers — soldiers, peasants, and prisoners — worked and often died building its nearly 21,000 kilometers of walls, towers, and fortifications.",
    "yongle-emperor": "The Yongle Emperor moved China's capital to Beijing in 1420 and built the Forbidden City — a complex of nearly 1,000 buildings — in just 14 years using a workforce of up to a million laborers. He also sponsored the great treasure voyages of Zheng He, sending fleets of massive ships far beyond any European explorer's reach decades before Columbus ever set sail.",
    "empress-dowager-cixi": "Empress Dowager Cixi effectively ruled China for 47 years from behind the scenes, making her one of the most powerful women in Chinese history, and she modernized the Chinese military and economy while resisting full westernization. She was famously blamed for diverting naval funds to rebuild the Summer Palace's Marble Boat — but modern historians note she is also scapegoated for many of China's problems that were not her fault.",
    "zheng-he": "Zheng He was a Chinese Muslim admiral who commanded seven extraordinary voyages between 1405 and 1433 AD, leading fleets of massive treasure ships up to 120 meters long — far larger than any European ship of the time — to Southeast Asia, India, Arabia, and the East African coast. His voyages established trade relationships and Chinese prestige across the Indian Ocean world, but after his death China turned inward and the great voyages were abandoned.",
    "terracotta-sculptor": "The Terracotta Army was created by thousands of artisans working in assembly-line fashion, with different workshops producing heads, torsos, legs, and arms that were assembled and then hand-finished to give each soldier a unique face. Analysis of the clay has shown that the army was painted in bright colors when first created, though the paint disintegrated when the figures were exposed to air after excavation.",
    "terracotta-farmer": "Yang Zhifa was one of a group of farmers who accidentally discovered the Terracotta Army in March 1974 while digging a well during a drought. He became a celebrity, spending decades signing books at the museum site, and his accidental discovery led to one of the greatest archaeological finds of the 20th century.",
    "terracotta-general": "General Meng Tian served Qin Shi Huang and commanded the massive labor force — including 300,000 soldiers — that built the first unified Great Wall along China's northern frontier, connecting and extending existing walls. He was the most powerful military commander in China, but after the emperor's death he was falsely accused of crimes by a court conspiracy and forced to commit suicide.",
    "suryavarman-ii": "Suryavarman II built Angkor Wat between around 1113 and 1150 AD as a temple dedicated to the Hindu god Vishnu and as his own mausoleum, covering the walls with over half a mile of intricate bas-relief carvings depicting Hindu myths and battle scenes. Angkor Wat is the largest religious monument ever constructed, covering an area of nearly 400 acres and still dominating the landscape today.",
    "angkor-sculptor": "The bas-reliefs of Angkor Wat contain over 1,200 square meters of intricate carved scenes, including a famous 49-meter panel showing the 'Churning of the Sea of Milk' from Hindu mythology with 88 gods and 92 demons pulling a giant serpent around a mountain. The level of carving detail — including individual facial expressions, jewelry, and fabric folds — reflects the sophisticated artistry of Khmer craftsmen.",
    "jayavarman-vii": "Jayavarman VII was the most prolific builder among all Khmer kings, constructing Angkor Thom and the Bayon temple with its 216 enormous carved faces, as well as hospitals, rest houses, and roads across the empire. After converting to Buddhism, he reoriented the Khmer Empire from Hinduism to Theravada Buddhism, a transformation that had lasting effects on Southeast Asian religion and culture.",
    "ashikaga-yoshimitsu": "Ashikaga Yoshimitsu was the third Shogun of the Muromachi shogunate who built the Kinkaku-ji (Temple of the Golden Pavilion) as his personal retirement villa in 1397, covering it in gold leaf as a symbol of his enormous political and economic power. He ended the period of rival emperors that had divided Japan and re-established relations with China, importing Chinese culture, art, and Zen Buddhism that deeply influenced Japanese aesthetics.",
    "murasaki-shikibu": "Murasaki Shikibu was a lady-in-waiting at the Japanese imperial court who wrote 'The Tale of Genji' around the year 1000 AD, a 1,000-page novel widely considered the world's first novel and the masterpiece of Japanese literature. She wrote in a period when educated women in Japan were expected to know Chinese characters (the language of government), and she reportedly had to learn Chinese secretly because such learning was considered improper for women.",
    "zen-monk": "Musō Soseki was one of Japan's most influential Zen Buddhist monks, designing several of Japan's most celebrated gardens including Saihō-ji (the Moss Garden) and Tenryū-ji in Kyoto, which combine philosophy, poetry, and nature into meditative landscapes. He served as spiritual advisor to multiple shoguns and emperors, and his approach to garden design — using borrowed landscape, negative space, and natural materials — defined the Japanese garden aesthetic.",
    "sailendra-king": "King Samaratungga of the Sailendra dynasty commissioned the construction of Borobudur around 825 AD, a massive nine-level Buddhist monument containing 2 million cubic feet of stone, 504 Buddha statues, and 2,672 relief panels depicting Buddhist teachings. Borobudur was designed as a three-dimensional mandala, and walking its galleries from the base to the summit was meant to symbolize the Buddhist journey from the world of desire to enlightenment.",
    "borobudur-sculptor": "The relief panels at Borobudur are one of the most extraordinary artistic achievements of the ancient world, depicting over 1,300 scenes from Buddhist texts and from daily life in 8th and 9th century Java — including ships, musicians, markets, and royal courts that provide a rare visual record of the era. Each panel was carved in situ directly on the stone after it had been laid in place, requiring the sculptors to plan the entire composition in their heads.",
    "stamford-raffles": "Sir Stamford Raffles was the British colonial administrator who founded the city of Singapore in 1819, a decision that transformed the region's trade and eventually created one of the world's most prosperous cities. He also 'rediscovered' the overgrown Borobudur monument in 1814 during his tenure as governor of Java and ordered its first systematic study and documentation.",
    "sejong-the-great": "King Sejong the Great of Joseon Korea created the Hangul alphabet in 1443, a phonetic writing system specifically designed to be easy to learn so that ordinary Koreans could become literate — unlike the complex Chinese characters used by the elite. He also established a royal research institute that developed new astronomical instruments, agricultural manuals, and medical encyclopedias that improved Korean science and daily life.",
    "jang-yeong-sil": "Jang Yeong-sil was a scientist of low social rank who was elevated to the royal court by King Sejong's appreciation for talent, and he invented Korea's first rain gauge, a water clock, and sundials that were used to set Korea's official time. His innovations came during a period when Korea was establishing scientific independence from China, and his rain gauge predated European rain gauges by more than 200 years.",
    "shin-saimdang": "Shin Saimdang was a Korean artist, poet, calligrapher, and scholar of the 16th century who is celebrated as a model of Confucian female virtue but was also a genuinely accomplished artist known for her exquisite paintings of plants, insects, and landscapes. She appears on the South Korean 50,000-won banknote, making her one of the few historical women honored on modern currency anywhere in the world.",
    "toyotomi-hideyoshi": "Toyotomi Hideyoshi rose from being born a peasant with no surname to becoming the supreme ruler of Japan, unifying the country after a century of civil war through military genius and extraordinary political cunning. He launched two invasions of Korea in 1592 and 1597 that devastated the Korean peninsula, and the wars are still remembered as a source of historical tension between Japan and Korea.",
    "miyamoto-musashi": "Miyamoto Musashi was a Japanese swordsman who fought in over 60 duels starting at age 13 and never lost, developing a distinctive two-sword fighting style called Niten Ichi-ryū. He wrote 'The Book of Five Rings' late in his life, a treatise on strategy and martial arts philosophy that is still studied by martial artists and business strategists today.",
    "lady-sen": "Senhime was the granddaughter of the shogun Tokugawa Ieyasu who was married at age 7 to Toyotomi Hideyori to cement a political alliance, and after the fall of Osaka Castle was rescued and later became a resident of Himeji Castle. Her life story — passed between political marriages and caught between feuding warlords — illustrates how aristocratic women in feudal Japan had little control over their own destinies.",
    "anangu-elder": "The Anangu people have lived in the desert around Uluru for at least 30,000 years, one of the longest continuous cultural connections to land anywhere in the world. Uluru is sacred to the Anangu under their ancestral law known as Tjukurpa, which contains the stories, rules, and knowledge that connect the people to the land and to each other.",
    "anangu-tracker": "Traditional Anangu tracking skills — the ability to read footprints, broken twigs, disturbed soil, and animal behavior to find water, food, and people in one of the world's harshest deserts — represent thousands of years of accumulated ecological knowledge. This knowledge was passed down through generations through Tjukurpa and is still practiced today, and some of it has been used to help find lost hikers in the outback.",
    "anangu-artist": "Anangu artists are known for their distinctive dot painting style, which evolved in the 1970s when Aboriginal men began painting their ceremonial sand drawings on canvas for sale — a tradition that transformed into a global art movement worth hundreds of millions of dollars annually. The paintings encode cultural and spiritual knowledge within their patterns, and different parts of a painting's meaning may be shared with outsiders while deeper layers remain secret.",
    "hone-heke": "Hone Heke was the first Māori chief to sign the Treaty of Waitangi in 1840, but he soon became disillusioned with British colonialism and was the first to rebel against it, famously chopping down the British flagpole at Kororāreka four times as an act of defiance. The flagpole and what it represented — British sovereignty — made it a powerful political symbol, and Heke's actions started the Northern War of 1845.",
    "meri-te-tai-mangakahia": "Meri Te Tai Mangakāhia was a pioneering Māori activist who in 1893 became the first person to argue before the Māori Parliament that women should have the right to vote and stand for election — the same year New Zealand became the first country in the world to give women the right to vote. Her speech challenged both the colonial government and traditional male authority within Māori governance.",
    "maori-navigator": "Kupe is the legendary Polynesian navigator credited in Māori oral tradition with discovering Aotearoa (New Zealand) around 1000 AD, sailing from Hawaiki in a double-hulled canoe using the stars, ocean swells, bird flight patterns, and cloud formations to navigate thousands of miles across open ocean. Māori navigation techniques were among the most sophisticated in the ancient world.",
    "kukulcan-priest": "The main pyramid at Chichén Itzá is dedicated to the feathered serpent god Kukulcán, and it was built with astronomical precision — at the spring and autumn equinoxes, the shadows on the pyramid's staircase create the optical illusion of a giant serpent descending from the sky. Maya priests used this and other astronomical alignments to set the agricultural and religious calendar that governed every aspect of Maya society.",
    "maya-scribe": "Lady Xoc was a Maya noblewoman at Yaxchilán whose stone lintels — carved monuments showing her performing blood sacrifice rituals — are among the finest examples of Classic Maya sculpture and provide important insight into the religious roles of elite Maya women. Blood sacrifice, including ritual bloodletting from the tongue and body, was central to Maya religious practice as a way of communicating with ancestors and gods.",
    "maya-ballplayer": "The Mesoamerican ballgame played at Chichén Itzá and other Maya cities was not just a sport — it was a sacred ritual reenactment of the Hero Twins' defeat of the lords of death from the Popol Vuh. Players had to strike a heavy rubber ball with their hips through a stone ring mounted on the wall, and some carvings suggest that players — possibly the losing team, possibly the winners — were sacrificed at the game's conclusion.",
    "teotihuacan-architect": "Teotihuacan was planned and built on a precise grid aligned to the stars, with its main avenue — the Street of the Dead — oriented 15.5 degrees east of north to align with the setting point of the Pleiades star cluster, which had deep significance in Mesoamerican religion and calendars. At its peak around 500 AD, Teotihuacan was home to roughly 125,000 people, making it one of the largest cities in the ancient world.",
    "teotihuacan-mural-painter": "The murals of Teotihuacan are among the most sophisticated painting traditions of the ancient Americas, covering the walls of temples, palaces, and apartment compounds with detailed images of gods, feathered serpents, jaguars, and mythological scenes in vivid red, green, yellow, and blue mineral pigments. Unlike Maya art, Teotihuacan murals rarely depict specific rulers or battles, suggesting its society may have been organized differently from typical Mesoamerican city-states.",
    "teotihuacan-trader": "Teotihuacan was the dominant commercial power of Mesoamerica at its height, controlling the trade in obsidian — the volcanic glass used to make the sharpest cutting tools in the pre-metal Americas — from quarries near modern-day Mexico City. Teotihuacan obsidian, pottery, and religious objects have been found across a vast area from northern Mexico to Guatemala, showing how far the city's commercial and cultural influence reached.",
    "ancestral-puebloan-builder": "The cliff dwellings of Mesa Verde were built by the Ancestral Puebloan people between about 1190 and 1300 AD, constructed directly into the natural alcoves of the canyon walls using sandstone blocks, wooden beams, and a mud mortar that still holds firm today. The largest, Cliff Palace, has 150 rooms and 23 kivas (ceremonial chambers) and housed an estimated 100–150 people in an apartment complex that required extraordinary engineering to build in such a difficult location.",
    "puebloan-potter": "Ancestral Puebloan potters created beautiful black-on-white ceramic vessels without a potter's wheel, hand-coiling clay into shape and decorating them with intricate geometric patterns that served both practical and ceremonial purposes. The distinctive pottery styles varied by region and changed over time, allowing archaeologists to trace trade networks and population movements across the Southwest.",
    "puebloan-astronomer": "Mesa Verde's Sun Temple and other structures were built with walls precisely aligned to capture sunlight at the solstices and equinoxes, demonstrating that the Ancestral Puebloans tracked astronomical events to coordinate their agricultural and ceremonial calendar. The role of the Sun Watcher — the person responsible for observing the sun's position and telling the community when to plant, harvest, and hold ceremonies — was one of the most important in Puebloan society.",
    "benjamin-franklin": "Benjamin Franklin was one of America's founding fathers who signed the Declaration of Independence and the U.S. Constitution, but he was also one of the most celebrated scientists of his age — his kite experiment demonstrated that lightning is electrical, leading to his invention of the lightning rod that saved countless buildings and ships from destruction. He was also the first Postmaster General of the United States, founded America's first public library, and learned to speak five languages.",
    "abigail-adams": "Abigail Adams was the wife of President John Adams and mother of President John Quincy Adams, and her extensive correspondence with her husband during the Revolutionary War provides one of the most vivid firsthand accounts of life in early America. In a famous 1776 letter, she urged her husband to 'remember the ladies' when forming the new government — one of the earliest calls for women's rights in American political history.",
    "james-forten": "James Forten was born free in Philadelphia in 1766 and became one of the wealthiest African Americans in the early United States, building a sail-making business that employed 40 workers both Black and white. He used his wealth and influence to support the abolitionist movement, helped fund William Lloyd Garrison's antislavery newspaper 'The Liberator,' and wrote influential pamphlets arguing against laws that restricted Black rights.",
    "pachacuti": "Pachacuti was the Inca emperor who transformed a small kingdom into the Tawantinsuyu — the Inca Empire — the largest empire in pre-Columbian America, stretching 4,300 km from present-day Colombia to Chile. He built Machu Picchu around 1450 AD as a royal estate and religious retreat, and the site's precise stone masonry was constructed without mortar, using thousands of precisely fitted stones that have withstood centuries of earthquakes.",
    "inca-engineer": "The Inca had no written language, but they recorded complex numerical and possibly narrative information using quipus — knotted cords of various colors and lengths — which were used to record census data, tribute amounts, and historical events. Inca engineers also built over 40,000 kilometers of roads, bridges made of braided grass, and an agricultural terrace system (andenes) that transformed steep Andean slopes into productive farmland still used today.",
    "hiram-bingham": "Hiram Bingham III was an American historian and explorer who was guided to Machu Picchu by a local boy in July 1911, and his photographs and writings introduced the site to the outside world, though local people had never forgotten its existence. He removed thousands of artifacts from the site, taking them to Yale University, and the Peruvian government spent decades demanding their return — a dispute finally settled in 2011 when Yale returned the collection.",
    "moai-carver": "The moai of Rapa Nui (Easter Island) are monolithic stone statues carved from compressed volcanic ash called tuff, and the largest ever erected stands nearly 10 meters tall and weighs over 80 tons. New research has shown that the moai were likely 'walked' upright to their locations using ropes and a rocking motion — a technique demonstrated successfully by modern researchers.",
    "rapa-nui-navigator": "The settlement of Rapa Nui (Easter Island) by Polynesian navigators around 1000–1200 AD was one of the most remarkable feats of open-ocean navigation in human history, as the island sits over 2,000 kilometers from the nearest inhabited land in any direction. Polynesian navigators used the stars, ocean swells, bird behavior, phosphorescent plankton, and cloud formations to find tiny islands across millions of square miles of open Pacific Ocean.",
    "rapa-nui-birdman": "The Birdman cult at Rapa Nui was an annual competition in which chiefs' representatives raced down a cliff, swam through shark-infested waters to a nearby islet, and collected the first sooty tern egg of the season — the winner's patron chief became the island's sacred ruler for the year. The cult emerged after the decline of moai construction, possibly representing a social and religious reorganization of island society after the environmental collapse caused by deforestation.",
    "jasaw-chan-kawil": "Jasaw Chan K'awiil I was the king of Tikal who reversed decades of political decline by defeating the rival city of Calakmul in 695 AD and ushering in Tikal's greatest period of prosperity and monument-building. He was buried with extraordinary wealth beneath Temple I — the towering pyramid that faces Temple II across Tikal's Great Plaza — and his jade-masked burial was discovered by archaeologists in 1962.",
    "tikal-chocolate-maker": "Cacao was first cultivated and consumed by the ancient Maya of the lowland rainforests, and Tikal's elite drank a frothy, bitter chocolate beverage made by fermenting, roasting, and grinding cacao beans — often flavored with chili, vanilla, or annatto — served in tall cylindrical ceramic vessels decorated with Maya glyphs. Chemical analysis of residues in Maya vessels found at Tikal has confirmed the presence of theobromine, the chemical marker of cacao, in vessels dating back over 2,500 years.",
    "tikal-astronomer": "Maya astronomers at Tikal tracked the movements of the sun, moon, Venus, and other planets with extraordinary precision using naked-eye observation from precisely aligned buildings, and produced astronomical tables accurate enough to predict solar eclipses centuries into the future. The Maya Long Count calendar was so sophisticated that it could place any date within a span of millions of years, and Maya date calculations were more accurate than the European calendar of the same period.",
    "abraham-lincoln": "Abraham Lincoln was the 16th President of the United States who led the country through the Civil War and issued the Emancipation Proclamation in 1863, declaring enslaved people in Confederate states to be free — a decision that transformed the war into a fight explicitly about the abolition of slavery. He was assassinated by John Wilkes Booth at Ford's Theatre in Washington D.C. on April 14, 1865, just five days after the Confederate surrender effectively ended the war.",
    "harriet-tubman": "Harriet Tubman escaped slavery in 1849 and then made approximately 13 missions back into the South, personally leading around 70 enslaved people to freedom using the Underground Railroad network of safe houses and secret routes. During the Civil War she served as a spy and scout for the Union Army and in 1863 commanded the Combahee River Raid, liberating over 700 enslaved people — making her the first woman in American history to lead an armed military mission.",
    "joshua-chamberlain": "Colonel Joshua Lawrence Chamberlain was a former college professor who led the 20th Maine Volunteer Infantry Regiment in a desperate defense of Little Round Top at the Battle of Gettysburg on July 2, 1863, ordering a bayonet charge when his men ran out of ammunition and helping prevent the Union line from being flanked — an action many historians credit with saving the battle and possibly the war. He was awarded the Medal of Honor for his actions and was chosen by General Grant to receive the Confederate surrender at Appomattox.",
    "timur": "Timur, known in the West as Tamerlane, was a 14th-century Central Asian conqueror of Turco-Mongol descent who built an empire stretching from Turkey to India, leaving a trail of destruction that included pyramids of skulls outside defeated cities. Despite his brutality in conquest, he was an extraordinary patron of art and architecture who transformed Samarkand into one of the most beautiful cities in the Islamic world.",
    "ulugh-beg": "Ulugh Beg was the Timurid sultan of Samarkand and one of the greatest astronomers of the pre-telescopic era, building a massive sextant with a radius of over 40 meters into the hillside to measure the positions of stars with extraordinary accuracy. His star catalogue, completed in 1437, catalogued 1,018 stars and his measurements of the Earth's axial tilt were accurate to within a fraction of a degree — comparable to what European astronomers achieved 200 years later with telescopes.",
    "silk-road-merchant": "Samarkand was one of the most important cities on the Silk Road, sitting at the junction of routes connecting China, India, Persia, and the Mediterranean world, and the Sogdian merchants who operated from there were the greatest traders of the ancient world, carrying silk, spices, and precious goods across thousands of miles. Sogdian letters discovered in watchtowers along the Great Wall of China, dating to around 313 AD, are some of the earliest surviving commercial correspondence ever found.",
    "king-minos": "King Minos is the legendary ruler of Crete in Greek mythology who commissioned the labyrinth to contain the Minotaur — the half-man, half-bull creature born of his wife and a divine bull — and demanded tribute of young Athenians to be sacrificed to it. The Palace of Knossos, excavated by Arthur Evans from 1900 onward, revealed a complex multi-story structure that likely inspired the labyrinth myth, and the Minoan civilization that built it was the first advanced civilization in Europe.",
    "minoan-priestess": "The Minoan civilization that flourished on Crete between roughly 2700 and 1450 BC appears to have accorded women high religious and possibly political status — Minoan frescoes and figurines frequently depict women in elaborate dress presiding over religious ceremonies, handling snakes, and participating in athletic events such as bull-leaping. The Minoans left behind a writing system called Linear A that has never been deciphered, leaving many aspects of their society a mystery.",
    "minoan-bull-leaper": "The bull-leaping depicted in Minoan frescoes — athletes vaulting over charging bulls by grabbing the horns and somersaulting over the back — is one of the most iconic images of the Bronze Age Mediterranean, though scholars still debate whether it was a real athletic performance, a religious ritual, or a mythological scene. Bronze figurines of bull-leapers have been found across the eastern Mediterranean, suggesting this practice was known well beyond Crete.",
    "leif-erikson": "Leif Erikson was a Norse Viking explorer who reached North America around 1000 AD — approximately 500 years before Columbus — and established a settlement at a place he called Vinland, which archaeologists have identified with L'Anse aux Meadows in Newfoundland, Canada. His voyage was largely forgotten in European history until the 19th century, when archaeologists began investigating Norse sagas that described the journey.",
    "viking-queen": "Queen Asa was a 9th-century Norse queen whose burial in the Oseberg ship — discovered in Norway in 1904 — is the richest Viking burial ever found, containing a fully preserved longship, two female skeletons (one believed to be Asa herself), sleds, a cart, horses, bedding, and everyday objects. The Oseberg burial gives us our best insight into the material culture and beliefs of the Viking world.",
    "viking-shipbuilder": "Viking longships were among the most technologically sophisticated watercraft of their time, with a shallow draft that allowed them to sail in open ocean and navigate shallow rivers, a flexible clinker-built hull that bent with the waves rather than breaking, and a symmetric design that allowed them to reverse direction without turning around. These design innovations allowed Vikings to raid coastal settlements by surprise, travel up rivers deep into Europe and Russia, and even cross the Atlantic to North America.",
    "indus-urban-planner": "Mohenjo-daro, built around 2500 BC in the Indus Valley (modern Pakistan), had one of the most sophisticated urban planning systems of the ancient world — with a grid layout, standardized baked-brick construction, a covered sewage and drainage system, and a public bath — centuries before similar infrastructure appeared in ancient Greece or Rome. The city housed an estimated 40,000 people, but archaeologists have found no evidence of kings, palaces, or temples, raising fascinating questions about how its society was organized.",
    "indus-bead-maker": "The Indus Valley Civilization was renowned for its skilled craft production, and Mohenjo-daro's bead-makers produced elaborate carnelian, steatite, and gold beads using a sophisticated drilling technique that created unusually long perforations in very hard stone. Indus beads have been found at archaeological sites from Mesopotamia to Afghanistan, showing how widely the civilization's artisans traded their products.",
    "indus-seal-maker": "The Indus Valley Civilization left behind over 4,000 carved stone seals depicting animals such as unicorns, tigers, and elephants alongside short inscriptions in an undeciphered script — making the Indus script one of the most significant unsolved mysteries in linguistics. The seals were likely used to mark ownership or authenticate goods in trade, and the fact that the same script appears across the entire Indus civilization suggests a shared administrative or commercial system.",
    "djenne-mason": "The Great Mosque of Djenné in Mali is the largest mud-brick building in the world and has been continuously maintained by the city's community through an annual collective replastering festival called the Crepissage, during which thousands of people work together to apply new mud to the entire exterior. The mosque is built in the Sudano-Sahelian architectural style, with its distinctive protruding wooden beams that serve as permanent scaffolding for the annual maintenance.",
    "djenne-scholar": "Djenné and nearby Timbuktu were major centers of Islamic scholarship in West Africa, with collections of manuscripts estimated in the hundreds of thousands that have survived for centuries in private family libraries. Ahmed Baba al-Massufi and other scholars wrote on topics including Islamic law, theology, history, and astronomy, demonstrating that medieval West Africa had a sophisticated written intellectual culture that Western historians long overlooked.",
    "djenne-trader-woman": "Djenné has been a market city for over a thousand years, and its Monday market — one of the largest in West Africa — takes place right in front of the Great Mosque in an ancient tradition of commerce that has continued largely uninterrupted for centuries. Women in Djenné have traditionally controlled much of the local trade, and the city's merchant families have maintained oral and written records of their commercial networks across the Sahara and along the Niger River.",
    "moctezuma-ii": "Moctezuma II was the Aztec emperor who ruled the Aztec Triple Alliance at its peak, controlling central Mexico and receiving enormous tribute in gold, feathers, cacao, and textiles from hundreds of subject states. When the Spanish conquistador Hernán Cortés arrived in 1519, Moctezuma initially welcomed him and was later taken hostage; he died in 1520 under disputed circumstances — Aztec accounts say the Spanish killed him, Spanish accounts claim the Aztecs stoned him when he tried to calm a revolt.",
    "aztec-chinampas-farmer": "Chinampas were artificial islands built by Aztec farmers in the shallow lakes around Tenochtitlán by layering mud, vegetation, and lake sediment to create remarkably fertile raised fields that could produce multiple harvests per year. This agricultural system transformed the swampy basin of the Valley of Mexico into the most productive farmland in Mesoamerica, feeding the Aztec capital of Tenochtitlán, which at its peak was one of the five largest cities in the world.",
    "malintzin": "Malintzin, also called La Malinche or Doña Marina, was a Nahua woman who was given to the Spanish conquistadors as a slave and became the essential interpreter and advisor of Hernán Cortés throughout the Spanish conquest of the Aztec Empire. She spoke both Nahuatl and Maya and learned Spanish, making her indispensable to the conquest, and her legacy in Mexican history is complex — some view her as a traitor, others as a survivor navigating an impossible situation.",
    "tiwanaku-architect": "Tiwanaku near Lake Titicaca in Bolivia was one of the most important pre-Columbian cities in South America, flourishing between roughly 500 and 1000 AD at an altitude of 3,850 meters — making it one of the highest urban civilizations in ancient history. Its builders erected massive stone monuments using precisely cut andesite and sandstone blocks weighing hundreds of tons, transported from quarries on the shores of Lake Titicaca using reed boats and llama caravans.",
    "tiwanaku-farmer": "The raised-field agriculture system developed around Lake Titicaca — known as suka kollus — consisted of elevated planting beds separated by water-filled canals that absorbed solar heat during the day and released it at night, protecting crops from the killing frosts common at high altitude. This agricultural system, which supported a population estimated at 500,000–1,000,000 people, was abandoned after the collapse of Tiwanaku and only rediscovered by archaeologists in the 1980s.",
    "tiwanaku-priest": "The Gateway of the Sun at Tiwanaku is a monolithic stone arch carved with an image of a central deity — the 'Staff God' — flanked by 48 winged figures, and it was probably the focal point of religious ceremonies associated with the sun, calendar, and agricultural cycle. Tiwanaku religion spread across a vast area of the Andes through missionaries, trade, and cultural influence, and its iconography influenced later Andean civilizations including the Inca.",
    "nazca-line-maker": "The Nazca Lines are a collection of over 800 straight lines, 300 geometric figures, and 70 animal and plant figures etched into the desert floor of southern Peru by removing the reddish-brown iron oxide-coated stones to reveal the yellowish-grey ground beneath. The figures include a hummingbird 93 meters long, a spider 46 meters wide, and a monkey with a spiraling tail, and they have been continuously visible for over 1,500 years because the extremely dry, windless climate of the Nazca Desert preserves them.",
    "nazca-water-finder": "The Nazca people developed an extraordinary underground aqueduct system called puquios — spiral ramp-shaped entrance shafts leading to underground channels that tapped into aquifers buried deep beneath the desert. These aqueducts, still partially functional today, allowed the Nazca to farm the desert and sustain cities of thousands of people in one of the driest places on earth without any surface rivers.",
    "nazca-weaver": "The Nazca culture produced some of the finest textiles in the ancient Americas, weaving incredibly fine cloths from alpaca fiber with up to 200 threads per centimeter and dyeing them in over 190 distinct colors using plant and mineral dyes. Many of the same animal images found in the Nazca Lines also appear on Nazca textiles and pottery, suggesting a shared cosmological system of symbols that the people used across multiple art forms.",
    "sultan-ali-ibn-al-hasan": "Sultan Ali ibn al-Hasan founded the Kilwa Sultanate on a small island off the coast of present-day Tanzania around 960 AD, establishing what would become the most powerful trading city on the East African coast. Kilwa controlled the gold trade from the Zimbabwe Plateau to the outside world and became fabulously wealthy, with the great traveler Ibn Battuta describing it in 1331 as one of the most beautiful cities in the world.",
    "kilwa-coin-maker": "Kilwa was the first sub-Saharan African city to mint its own coins, beginning around the 10th century — evidence of a sophisticated monetary economy and commercial system. Kilwa's coins have been found as far away as Australia, where a small hoard of them was discovered in 1944, raising fascinating historical questions about pre-European contact between East Africa and Southeast Asia or Australia.",
    "ibn-battuta-host": "Ibn Battuta was a 14th-century Moroccan traveler who covered roughly 75,000 miles over 29 years — visiting nearly every Muslim country and many non-Muslim ones — and his account 'Rihla' (The Journey) provides the most detailed picture of the medieval Islamic world available. When he visited Kilwa in 1331, he was hosted by the sultan and was deeply impressed by the city's wealth, charitable institutions, and the piety of its ruler.",
}

with open("/Users/jessieli/Desktop/TimeFriends/src/data/landmarks.json", "r", encoding="utf-8") as f:
    data = json.load(f)

patched = 0
missing = []

for landmark in data["landmarks"]:
    for figure in landmark.get("figures", []):
        fid = figure["id"]
        if fid in descriptions:
            figure["description"] = descriptions[fid]
            patched += 1
        else:
            missing.append(fid)

with open("/Users/jessieli/Desktop/TimeFriends/src/data/landmarks.json", "w", encoding="utf-8") as f:
    json.dump(data, f, indent=2, ensure_ascii=False)

print(f"Patched {patched} figures.")
if missing:
    print(f"No description found for: {missing}")
else:
    print("All figures patched successfully.")
